Record Delivery
  Define estado, courier, reason As String;
  Define hora As Integer;
EndRecord

Algorithm Deliveries
  Define estado As String;
  Read estado;
  Define delivery As Delivery <- Delivery(estado, "", "", 0);
  If estado = "on its way" Then
    Read delivery.courier;
    Write "On its way with ", delivery.courier;
  Else
    If estado = "canceled" Then
      Read delivery.reason;
      Write "Canceled: ", delivery.reason;
    Else
      Write "Pending";
    EndIf
  EndIf
EndAlgorithm

