evaluation.reference:
Variant Delivery
  Case Pending
  Case OnItsWay(courier As String)
  Case Canceled(reason As String)
  Case Unknown(estado As String)
EndVariant

Function text <- Describe(delivery As Delivery)
  Define text As String <- "";
  Switch delivery Do
    Delivery.Pending: text <- "Pending";
    Delivery.OnItsWay(who): text <- "On its way with " + who;
    Delivery.Canceled(reason): text <- "Canceled: " + reason;
    Delivery.Unknown(estado): text <- "Unknown state: " + estado;
  EndSwitch
EndFunction

Algorithm Deliveries
  Define estado, detail As String;
  Read estado;
  Define delivery As Delivery <- Delivery.Unknown(estado);
  If estado = "pending" Then
    delivery <- Delivery.Pending;
  EndIf
  If estado = "on its way" Then
    Read detail;
    delivery <- Delivery.OnItsWay(detail);
  EndIf
  If estado = "canceled" Then
    Read detail;
    delivery <- Delivery.Canceled(detail);
  EndIf
  Write Describe(delivery);
EndAlgorithm
